function switchSettings(section,record=true){settingsSection=section;for(const name of ['general','appearance','server','network','storage','pxe','users']){$('settings-'+name).hidden=name!==section;$('settings-'+name+'-tab').classList.toggle('active',name===section);}if(record&&tab==='settings')rememberPortalNavigation();refresh();}
$('settings-pxe-tab').addEventListener('click',()=>switchSettings('pxe'));
$('settings-users-tab').addEventListener('click',()=>switchSettings('users'));
$('open-users').addEventListener('click',()=>{switchSettings('users');switchTab('settings');});
async function refreshUsers(){const data=await api('/users');if(!webSession||tab!=='settings'||settingsSection!=='users')return;users=data;const current=webSession.user.id;const selected=$('password-user').value||current;$('users-table').innerHTML=table(['Username','Access','Status','Password','Actions'],users.map(u=>[esc(u.username)+(u.id===current?' <small>(you)</small>':''),'Administrator',u.enabled?'Enabled':'Disabled',u.default_password?'<span class="badge warn">Default password</span>':'Custom password','<button class="secondary compact" data-user-password="'+esc(u.id)+'">Change password</button> <button class="secondary compact" data-user-toggle="'+esc(u.id)+'" data-enabled="'+(!u.enabled)+'"'+(u.enabled&&users.filter(x=>x.enabled).length===1?' disabled':'')+'>'+(u.enabled?'Disable':'Enable')+'</button>']));if(document.activeElement!==$('password-user')){$('password-user').innerHTML=users.map(u=>'<option value="'+esc(u.id)+'"'+(u.id===selected?' selected':'')+'>'+esc(u.username)+'</option>').join('');}}
$('users-table').addEventListener('click',async e=>{const button=e.target.closest('button');if(!button)return;if(button.dataset.userPassword){$('password-user').value=button.dataset.userPassword;$('new-password').focus();return;}if(!button.dataset.userToggle)return;button.disabled=true;try{await api('/users/'+button.dataset.userToggle+'/availability',{method:'PUT',body:JSON.stringify({enabled:button.dataset.enabled==='true'})});if(button.dataset.userToggle===webSession.user.id&&button.dataset.enabled==='false'){signedOut();message('Your account is disabled.');}else{await refreshUsers();message('User updated.');}}catch(e){message(e.message,true);}finally{button.disabled=false;}});
$('password-form').addEventListener('submit',async e=>{e.preventDefault();if($('new-password').value!==$('confirm-password').value){message('Passwords do not match.',true);return;}const button=e.submitter;button.disabled=true;const id=$('password-user').value;try{await api('/users/'+id+'/password',{method:'PUT',body:JSON.stringify({password:$('new-password').value})});$('new-password').value='';$('confirm-password').value='';if(id===webSession.user.id){signedOut();message('Password changed. Sign in with your new password.');}else{message('Password changed.');await refreshUsers();}}catch(e){message(e.message,true);}finally{button.disabled=false;}});
$('user-form').addEventListener('submit',async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;try{await api('/users',{method:'POST',body:JSON.stringify({username:$('new-username').value.trim(),password:$('user-password').value})});$('new-username').value='';$('user-password').value='';message('User added.');await refreshUsers();}catch(e){message(e.message,true);}finally{button.disabled=false;}});

$('driver-tag-form').addEventListener('submit',async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;try{await api('/driver-library/'+$('tag-driver').value+'/tags',{method:'POST',body:JSON.stringify({manufacturer:$('tag-manufacturer').value.trim(),model:$('tag-model').value.trim(),windows_build:$('tag-build').value.trim(),hardware_test_passed:$('tag-tested').checked,validation_note:$('tag-note').value.trim()})});message('Model tag added. Existing driver files reused.');$('tag-tested').checked=false;await refresh();}catch(e){message(e.message,true);}finally{button.disabled=false;}});

let websitePreferences={site_name:'re-pxe',refresh_seconds:3,driver_stale_days:90,notes:''},websiteDirty=false,lastAutomaticRefresh=0;
let driverRows=[],driverPage=0,deleteIds=[];const selectedDrivers=new Set();
const filterIds=['search','provider','class','model','build','usage','before','min','max','sort','order','group-by'];
const dateText=value=>value?new Date(value).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'}):'Never recorded';
function driverOptions(id,values,label){const input=$('driver-'+id),previous=input.value;if(document.activeElement===input)return;input.innerHTML='<option value="">'+esc(label)+'</option>'+[...new Set(values.filter(Boolean))].sort((a,b)=>a.localeCompare(b)).map(v=>'<option value="'+esc(v)+'">'+esc(v)+'</option>').join('');input.value=values.includes(previous)?previous:'';}
function renderDriverLibrary(data){driverRows=data;const existing=new Set(data.map(r=>r.id));for(const id of selectedDrivers)if(!existing.has(id))selectedDrivers.delete(id);driverOptions('provider',data.map(r=>r.provider),'All providers');driverOptions('class',data.map(r=>r.class),'All classes');driverOptions('model',data.flatMap(r=>r.tags.map(t=>t.manufacturer+' / '+t.model)),'All models');driverOptions('build',data.flatMap(r=>r.tags.map(t=>t.windows_build)),'All builds');const previous=$('tag-driver').value;$('tag-driver').innerHTML='<option value="">Choose a driver…</option>'+data.map(r=>'<option value="'+esc(r.id)+'"'+(r.id===previous?' selected':'')+'>'+esc(r.name+' · '+(r.version||r.content_hash.slice(0,12)))+'</option>').join('');renderDrivers();}
function filteredDrivers(at=Date.now()){
 const v=id=>$('driver-'+id).value,search=v('search').trim().toLocaleLowerCase(),before=v('before')?new Date(v('before')+'T23:59:59.999').getTime():null;
 const rows=driverRows.filter(r=>{
  const tags=r.tags||[],age=r.last_used?(at-new Date(r.last_used).getTime())/86400000:null;
  const text=[r.name,r.provider,r.class,r.version,r.content_hash,r.group,...tags.flatMap(t=>[t.manufacturer,t.model,t.windows_build])].join(' ').toLocaleLowerCase();
  return (!search||text.includes(search))&&(!v('provider')||r.provider===v('provider'))&&(!v('class')||r.class===v('class'))&&(!v('model')||tags.some(t=>t.manufacturer+' / '+t.model===v('model')))&&(!v('build')||tags.some(t=>t.windows_build===v('build')))&&(!v('usage')||(v('usage')==='never'&&age===null)||(v('usage')==='used'&&age!==null)||(v('usage')==='recent'&&age!==null&&age<=30)||(v('usage')==='stale'&&age!==null&&age>websitePreferences.driver_stale_days))&&(before===null||(r.last_used&&new Date(r.last_used).getTime()<=before))&&(v('min')===''||r.size>=Number(v('min'))*1024**2)&&(v('max')===''||r.size<=Number(v('max'))*1024**2);
 });
 const key=v('sort')||'name',direction=v('order')==='desc'?-1:1;
 return rows.sort((a,b)=>{const value=r=>key==='last_used'||key==='created'?(r[key]?new Date(r[key]).getTime():0):key==='size'||key==='use_count'?(r[key]||0):String(r[key]||'');const x=value(a),y=value(b);return direction*(typeof x==='number'?x-y:x.localeCompare(y,undefined,{numeric:true,sensitivity:'base'}))||a.id.localeCompare(b.id);});
}
function driverGroupKey(r,key){if(key==='model')return [...new Set(r.tags.map(t=>t.manufacturer+' / '+t.model))].sort().join(', ')||'Untagged';if(key==='build')return [...new Set(r.tags.map(t=>t.windows_build))].sort().join(', ')||'No build tag';return r[key]||'Ungrouped';}
function renderDrivers(){
 const rows=filteredDrivers(),pages=Math.max(1,Math.ceil(rows.length/100));driverPage=Math.min(driverPage,pages-1);const visible=rows.slice(driverPage*100,(driverPage+1)*100),key=$('driver-group-by').value,groups=new Map();
 for(const r of visible){const label=key?driverGroupKey(r,key):'';if(!groups.has(label))groups.set(label,[]);groups.get(label).push(r);}
 $('row-count').textContent=rows.length+' of '+driverRows.length+' drivers · '+bytes(rows.reduce((n,r)=>n+r.size,0))+' logical';
 const row=r=>['<input class="driver-select" type="checkbox" data-driver="'+esc(r.id)+'" aria-label="Select '+esc(r.name)+'"'+(selectedDrivers.has(r.id)?' checked':'')+'>','<div class="name">'+esc(r.name)+'</div><div class="hash" title="'+esc(r.content_hash)+'">'+esc(r.content_hash.slice(0,16))+'…</div>'+(r.group?'<span class="badge">'+esc(r.group)+'</span>':''),esc(r.provider||'—')+' / '+esc(r.class||'—'),esc(r.version||'—'),'<div class="driver-tags">'+r.tags.map(t=>'<span class="badge">'+esc(t.manufacturer+' / '+t.model+' · '+t.windows_build)+'</span>').join(' ')+'</div>',bytes(r.size),'<div class="driver-usage">'+esc(dateText(r.last_used))+'<small><br>'+(r.use_count||0)+' jobs · '+(r.confirmed_count||0)+' confirmed</small></div>',esc(dateText(r.created))];
 $('table').innerHTML=rows.length?[...groups].sort((a,b)=>a[0].localeCompare(b[0])).map(([label,items])=>(key?'<div class="group-head"><strong>'+esc(label)+'</strong><button class="secondary compact" data-select-group="'+esc(label)+'">Select group</button></div>':'')+'<div class="driver-table">'+table(['Select','Driver','Provider / class','Version','Model tags','Size','Last used','Added'],items.map(row))+'</div>').join('')+(pages>1?'<div class="pagination"><button class="secondary" data-driver-page="'+(driverPage-1)+'"'+(driverPage===0?' disabled':'')+'>Previous</button><span>Page '+(driverPage+1)+' of '+pages+'</span><button class="secondary" data-driver-page="'+(driverPage+1)+'"'+(driverPage+1===pages?' disabled':'')+'>Next</button></div>':''):empty(driverRows.length?'No drivers match these filters':'No drivers published yet');
 updateDriverSelection();
}
function updateDriverSelection(){const filteredIds=new Set(filteredDrivers().map(r=>r.id));const selected=driverRows.filter(r=>selectedDrivers.has(r.id));$('driver-selection').textContent=selected.length+' selected · '+bytes(selected.reduce((n,r)=>n+r.size,0))+' logical'+(selected.some(r=>!filteredIds.has(r.id))?' (includes hidden rows)':'');$('driver-delete').disabled=!selected.length;$('driver-save-group').disabled=!selected.length;}
for(const id of filterIds)$('driver-'+id).addEventListener('input',()=>{driverPage=0;renderDrivers();});
$('driver-reset').addEventListener('click',()=>{for(const id of filterIds)$('driver-'+id).value=id==='sort'?'name':id==='order'?'asc':'';driverPage=0;renderDrivers();});
function selectDriverRows(rows){if(new Set([...selectedDrivers,...rows.map(r=>r.id)]).size>500){message('Select up to 500 drivers at a time.',true);return;}for(const r of rows)selectedDrivers.add(r.id);renderDrivers();}
$('driver-select-all').addEventListener('click',()=>selectDriverRows(filteredDrivers()));
$('driver-clear').addEventListener('click',()=>{selectedDrivers.clear();renderDrivers();});
$('table').addEventListener('change',e=>{const box=e.target.closest('input[data-driver]');if(!box)return;if(box.checked&&selectedDrivers.size>=500&&!selectedDrivers.has(box.dataset.driver)){box.checked=false;message('Select up to 500 drivers at a time.',true);return;}box.checked?selectedDrivers.add(box.dataset.driver):selectedDrivers.delete(box.dataset.driver);updateDriverSelection();});
$('driver-group-form').addEventListener('submit',async e=>{e.preventDefault();if(!selectedDrivers.size)return;const button=$('driver-save-group');button.disabled=true;try{await api('/driver-library/group',{method:'PUT',body:JSON.stringify({ids:[...selectedDrivers],name:$('driver-group-name').value.trim()})});await refresh();message('Driver groups saved.');}catch(e){message(e.message,true);}finally{updateDriverSelection();}});
$('driver-delete').addEventListener('click',async()=>{const button=$('driver-delete');button.disabled=true;try{deleteIds=[...selectedDrivers];$('driver-delete-error').hidden=true;const p=await api('/driver-library/delete-preview',{method:'POST',body:JSON.stringify({ids:deleteIds})});$('driver-delete-summary').textContent=p.count+' drivers · '+bytes(p.logical_bytes)+' logical. '+(p.blocked?p.blocked+' blocked; resolve dependencies before deleting.':'Storage recovery depends on shared files and retained archives.');$('driver-delete-entries').innerHTML=p.entries.map(r=>'<div class="driver-delete-item"><strong>'+esc(r.name)+'</strong> · '+bytes(r.size)+'<p class="hash">'+esc(r.id)+'</p>'+r.blockers.map(b=>'<p class="error">'+esc(b)+'</p>').join('')+r.retained_references.map(b=>'<p class="muted">Files retained for '+esc(b)+'</p>').join('')+'</div>').join('');$('driver-delete-confirm').disabled=!!p.blocked;$('driver-delete-dialog').showModal();}catch(e){message(e.message,true);}finally{updateDriverSelection();}});
$('driver-delete-cancel').addEventListener('click',()=>$('driver-delete-dialog').close());
$('driver-delete-confirm').addEventListener('click',async()=>{const button=$('driver-delete-confirm');button.disabled=true;try{const result=await api('/driver-library/delete',{method:'POST',body:JSON.stringify({ids:deleteIds})});for(const id of deleteIds)selectedDrivers.delete(id);$('driver-delete-dialog').close();await refresh();message(result.count+' drivers deleted · '+bytes(result.freed_bytes)+' unshared payload freed.'+(result.cleanup_deferred?' File cleanup was deferred.':'')+' '+result.note);}catch(e){$('driver-delete-error').textContent=e.message+' Cancel and reopen the review to refresh dependencies.';$('driver-delete-error').hidden=false;message(e.message,true);}finally{button.disabled=false;}});
function applyWebsitePreferences(value){websitePreferences=value;document.title=value.site_name;const brand=document.querySelector?.('.brand .brand-name');if(brand)brand.textContent=value.site_name;}
async function loadWebsitePreferences(){applyWebsitePreferences(await api('/website-settings'));}
for(const name of ['general','server','network','storage'])$('settings-'+name+'-tab').addEventListener('click',()=>switchSettings(name));
const stats=rows=>'<dl class="server-stats">'+rows.map(([name,value])=>'<div><dt>'+esc(name)+'</dt><dd>'+esc(value)+'</dd></div>').join('')+'</dl>';
const nullableBytes=n=>n==null?'Unavailable':bytes(n);
async function refreshServerSettings(){const section=settingsSection;if(section==='general'){const value=await api('/website-settings');applyWebsitePreferences(value);if(!websiteDirty){$('site-name').value=value.site_name;$('site-refresh').value=value.refresh_seconds;$('site-stale').value=value.driver_stale_days;$('site-notes').value=value.notes;}return;}if(section==='server'&&typeof refreshPortalUpdates==='function'){await refreshPortalUpdates();if(portalUpdateState?.maintenance||portalUpdateState?.busy)return;}const d=await api('/server-info');if(tab!=='settings'||settingsSection!==section)return;renderServerInfo(d);if(section==='storage'&&typeof loadBackups==='function')await loadBackups();}
function renderServerInfo(d){const r=d.runtime,s=d.storage,e=d.endpoints,boot=d.boot,n=d.network;
 $('server-information').innerHTML='<div class="info-grid"><div><h3>Application runtime</h3>'+stats([['Python',r.python],['Operating system',r.system+' · '+r.architecture],['Kernel',r.kernel],['API uptime',Math.floor(r.process_uptime_seconds/3600)+'h '+Math.floor(r.process_uptime_seconds%3600/60)+'m'],['Logical CPUs visible',r.cpu_count],['Load average (1 / 5 / 15 min)',r.load_average?.map(v=>v.toFixed(2)).join(' / ')||'Unavailable']])+'<p class="info-note">Runtime may run in a container. CPU and load may reflect the host; no physical disks are inspected.</p></div><div><h3>Memory</h3>'+stats([['System total visible',nullableBytes(r.memory_total)],['System available visible',nullableBytes(r.memory_available)],['Container memory used',nullableBytes(r.container_memory_used)],['Container memory limit',nullableBytes(r.container_memory_limit)]])+'<p class="info-note">System figures come from the runtime’s /proc view. Container figures use cgroup v2 where available.</p></div><div><h3>Published boot media</h3>'+stats([['Client version',boot?.version||'Not published'],['Validation',boot?(boot.validated?'Validated':'Testing'):'Unavailable'],['Secure Boot',boot?.secureBootValidated?'Validated':'Not validated'],['Custom PXE menu',d.custom_boot_menu?.enabled?'Enabled':'Disabled'],['DHCP boot filename',e.boot_filename]])+'<button class="secondary compact" data-guide="boot">Boot media guide</button>'+(d.downloads||[]).map(v=>'<p><a href="'+esc(v.url)+'">'+esc(v.name)+'</a><br><small>SHA-256</small><span class="hash release-hash">'+esc(v.sha256)+'</span></p>').join('')+(d.public_ca_sha256?'<p><small>Public CA SHA-256 embedded in media</small><span class="hash release-hash">'+esc(d.public_ca_sha256)+'</span></p>':'')+'</div><div><h3>Operator notes</h3><p>'+esc(websitePreferences.notes||'Add workshop notes in General settings.').replace(/\n/g,'<br>')+'</p></div></div>';
 $('network-information').innerHTML='<div class="info-grid"><div><h3>Server endpoints</h3>'+stats([['Server address',e.address],['HTTPS dashboard / API',e.website],...(e.website_http?[['HTTP dashboard',e.website_http]]:[]),['Boot download service',e.boot_http],['TFTP / DHCP option 66',e.tftp_server],['DHCP option 67',e.boot_filename]])+'</div><div><h3>Network sample</h3>'+stats([['Sample',n?(n.stale?'Stale · ':'Current · ')+dateText(n.sampled_at):'Unavailable'],['Upload',n?rate(n.tx_bytes_per_second):'Unavailable'],['Download',n?rate(n.rx_bytes_per_second):'Unavailable']])+'<p class="info-note">'+esc(n?'Interfaces: '+(Array.isArray(n.interfaces)?n.interfaces.map(v=>typeof v==='string'?v:v.name).join(', '):JSON.stringify(n.interfaces||[])):'Enable the server network sampler to populate traffic information.')+'</p></div></div><div class="driver-table">'+table(['Service','Status','Listener / firewall'],d.services.map(v=>[esc(v.name),esc(v.state),esc(v.port)]))+'</div><p class="info-note">Configured listeners do not prove reachability from clients. re-pxe uses your existing DHCP service; it does not manage DHCP or firewall settings through this page.</p>';
 $('storage-information').innerHTML='<div class="storage-bar" aria-label="Data filesystem '+Math.round(s.used/s.total*100)+' percent used"><span style="width:'+Math.max(0,Math.min(100,s.used/s.total*100))+'%"></span></div><div class="info-grid"><div><h3>Data filesystem</h3>'+stats([['Total',bytes(s.total)],['Used by all services',bytes(s.used)],['Free',bytes(s.free)],['Published images',s.images.count+' · '+bytes(s.images.bytes)],['Staging uploads',s.staging.count+' · '+bytes(s.staging.bytes)]])+'</div><div><h3>Driver storage</h3>'+stats([['Active individual drivers',s.drivers.count],['Logical library size',bytes(s.drivers.logical_bytes)],['Unique active payload',bytes(s.drivers.active_unique_bytes)],['All stored driver blobs',bytes(s.drivers.stored_blob_bytes)],['Sharing saved in active library',bytes(Math.max(0,s.drivers.logical_bytes-s.drivers.active_unique_bytes))],['Retired entries (metadata retained)',s.drivers.retired_count]])+'<p class="info-note">Logical size counts shared files once per driver. Stored blobs can include payload retained for saved configurations. Staging and other services consume additional space.</p></div></div><button class="secondary compact" data-guide="maintenance">Storage and backups guide</button>';
}
$('website-form').addEventListener('input',()=>{websiteDirty=true;});
$('website-form').addEventListener('submit',async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{const value=await api('/website-settings',{method:'PUT',body:JSON.stringify({site_name:$('site-name').value.trim(),refresh_seconds:Number($('site-refresh').value),driver_stale_days:Number($('site-stale').value),notes:$('site-notes').value})});applyWebsitePreferences(value);websiteDirty=false;message('Website settings saved.');}catch(e){message(e.message,true);}finally{b.disabled=false;}});

let activeGuide=null,guideEndpoints=null;
const guideSources={microsoft:'https://learn.microsoft.com/windows-hardware/manufacture/desktop/sysprep--generalize--a-windows-installation?view=windows-11',fog:'https://docs.fogproject.org/en/latest/management/web/dashboard/',iventoy:'https://www.iventoy.com/en/doc_ext_dhcp.html'};
const guides=[
{id:'workflows',title:'Routines: create, publish, assign and run',description:'The main workshop flow, disk binding, checkpoints and reports.',body:()=>`<ol><li>Open <strong>Routines</strong>. Add Boot, optional Inventory/ShredOS/checkpoints, Windows install and Finish. Use Erase only for a certificate without Windows.</li><li>ShredOS is included and prepared automatically. Choose a nwipe method, verification, rounds and disk policy. Every wipe uses the native nwipe screen and original per-drive PDF. Verify-only methods do not erase.</li><li>For Windows, build and publish validated WinPE boot media containing the re-pxe client (see Windows PXE setup), then prepare an image and enabled Windows preset. Select that preset inside the routine; it supplies the image, drivers and Windows Update policy.</li><li>Connect Success and Failure outputs; Failure can lead to a checkpoint or custom iPXE screen. Save the draft and publish a version. Choose the website default or assign a published routine to a MAC. Active jobs retain their original version and target.</li><li>Network boot the PC. Start assigned counts down for five seconds; any key stops it. Other routines are fetched dynamically. UniFi keeps <code>pxe/snponly.efi</code>.</li><li>Use <strong>Jobs</strong> for all steps, specifications, checkpoints and controls. Cancelling retains evidence; a running erase needs a local stop. Failed steps never silently repeat.</li><li>Use <strong>Reports</strong> for each routine's PDF, actual nwipe method, process history and linked certificate, including attempts that never reached Windows.</li></ol><p>The same unique disk identity and capacity stay pinned through erasure and Windows. Firmware setup depends on UEFI support. The full wipe-to-installed-Windows chain still require separate acceptance.</p>`},
{id:'files',title:'File explorer and iPXE background',description:'Real server data paths, editable scripts, background pictures and revision history.',body:()=>`<p><strong>File explorer</strong> shows every server file and folder under <code>/data</code>, including hidden files, database, backups, credentials, staging and published releases. No workspace folders are protected. Click to select, Ctrl-click for several items, Shift-click for a range and double-click to open. Use Back, Forward, Up, the folder address or breadcrumbs to navigate. New folder, New file, Upload, Open, Edit, Rename, Cut, Copy, Paste, Delete, Replace file and Download are available above the details view. F2 renames; Delete opens the delete confirmation; Ctrl+A/C/X/V selects, copies, cuts and pastes. Click a column heading to change sorting. Deleting folders also deletes their contents after confirmation. UTF-8 text opens in the editor with conflict checks and revision history; replace binary files with an upload. File operations stay within the server data directory.</p><p><strong>iPXE menu → Background image</strong> manages <code>/data/boot/custom/assets/ipxe-background.png</code>. Preview or replace it with a PNG, JPEG or WebP up to 5 MiB. Use the default background or restore a previous version. The image is decoded, resized and saved as a clean PNG with revision checks and backups. Uploaded pictures are displayed without added ASCII artwork or shading. Upload, reset or restore pictures in iPXE menu setup. Changes apply on the next menu load.</p><p><strong>iPXE menu</strong> controls labels, colors, text size and boot options. Each routine's Boot node sets its own delay from 0 to 300 seconds; zero waits for selection. Any key pauses the countdown and Refresh rearms it. Routine menu JSON edits <code>/data/config/routines-menu.json</code> with revision history. Custom iPXE steps snapshot scripts from <code>/data/boot/custom/scripts</code>. File editing does not publish a routine.</p><p>During ShredOS erasure, Dashboard and Jobs show each drive's measured percentage and remaining time. Stopped updates show Needs attention. Remove job retains Reports. An old software wipe requires confirmation that it is stopped locally; active or uncertain hardware erasure cannot be cleared this way.</p>`},
{id:'start',title:'Set up your first routine',description:'Choose a routine first, prepare its components, then publish and assign.',body:()=>`<ol><li>Sign in and check <strong>Setup wizard</strong>, server storage and the existing DHCP boot values. Use the permanent <code>pxe/snponly.efi</code> filename.</li><li>Create the routine in <strong>Routines</strong>. Erasure-only routines need ShredOS; Windows steps need validated WinPE boot media containing the re-pxe client, a published Windows image and an enabled Windows preset. Follow the Windows PXE setup guide before publishing.</li><li>Upload an offline generalized AMD64 WIM for Windows. Drivers enter the library automatically and match the exact model/build. A preset configures their Windows Update fallback and recovery options.</li><li>Save and publish the routine. Set the default on Dashboard/Routines or assign it to a MAC.</li><li>Validate each step on disposable fixtures and intended hardware. Follow its state in <strong>Jobs</strong> and retained evidence in <strong>Reports</strong>.</li></ol><p>Network boot selects the routine after five seconds unless a key is pressed. Subsequent Windows restarts use the installed disk. Saved drafts and assignments never write to a disk by themselves.</p>`},
{id:'network',title:'Network, DHCP and server address',description:'Required listeners, DHCP boot options, stable addresses and changing the server IP.',body:()=>{const e=guideEndpoints;return `<h3>UEFI x64 DHCP values</h3>${e?stats([['Next server / option 66',e.tftp_server],['Boot filename / option 67',e.boot_filename],['HTTPS dashboard',e.website],...(e.website_http?[['HTTP dashboard',e.website_http]]:[]),['Boot HTTP',e.boot_http]]):'<p>Server values are loading. See Settings → Network.</p>'}<p>Keep the existing router/DHCP service. re-pxe does not provide a DHCP or proxy-DHCP server. Reserve the server address. Start with clients on the same LAN; routed networks need correctly configured DHCP relay and firewall access.</p><h3>Client access</h3><ul><li>UDP 69 and UDP 30000–30031: TFTP bootstrap and transfer sockets.</li><li>TCP 8080: HTTP website. TCP 8089: approved boot downloads. TCP 8443: HTTPS website and application transfers.</li><li>TCP 445: optional host SMB shares for existing tools. TCP 8088 stays on server loopback.</li></ul><h3>Changing the IP</h3><ol><li>Schedule downtime and preserve the data directory, deploy/.env and gateway CA state.</li><li>Update the server’s own network configuration and reservation, then <code>REPXE_ADDRESS</code> in <code>deploy/.env</code>. Recreate the services with the updated environment.</li><li>Rebuild and republish the iPXE loader/WinPE media for the new boot and API URLs and public CA. Update DHCP options 66/67 and any bookmarked URLs.</li><li>Verify certificate trust, TFTP, boot HTTP and HTTPS from a client before resuming installs. The website cannot perform these host changes.</li></ol><p>Other projects expose different DHCP modes. See <a href="${guideSources.iventoy}" target="_blank" rel="noopener">iVentoy external DHCP documentation</a> for comparison; those modes are not implemented here.</p>`;}},
{id:'windows-media',title:'Windows PXE setup',description:'Resolve missing WinPE boot media before publishing a Windows routine.',body:()=>`<p>Windows routines need two separate images. <code>install.wim</code> from Windows installation media supplies the Windows editions to install; review the selected AMD64 edition in Images. The separate <strong>WinPE boot image</strong> runs the re-pxe client over PXE. Neither uploading install.wim nor running server setup builds WinPE.</p><ol><li>On your Linux Docker server, run <code>python3 tools/build_client.py</code> from the checkout. Copy <code>.local/client</code> and <code>client/media</code> to a Windows build workstation.</li><li>Install Microsoft ADK Deployment Tools and the WinPE add-on using <code>client/media/Install-WorkstationTools.ps1</code>. Copy the server's <strong>public</strong> CA certificate from <code>data/config/server-public-ca.crt</code> and review its SHA-256 with <code>Get-FileHash</code>.</li><li>Run <code>client/media/Build-WinPE.ps1</code> as administrator with the client, tests, new work/output paths and reviewed public CA. Use the complete command in <code>docs/windows.md</code>. Keep the ISO and its builder manifest; use normal media without lab startup switches.</li><li>Copy the generated media's <code>sources/boot.wim</code>, <code>Boot/BCD</code>, <code>Boot/boot.sdi</code> and <code>EFI/Boot/bootx64.efi</code> into the server's <code>.local/pxe</code>. Copy the ISO's <code>.json</code> builder manifest back too. Run <code>python3 tools/build_wimboot.py</code>; server setup has already staged the matching iPXE loader and source files.</li><li>Install <code>tools/requirements.txt</code>, publish the native client with <code>tools/publish_client.py</code>, and stage the WinPE bundle for acceptance testing. Follow <code>docs/windows.md</code> for the full SSH commands. After acceptance on disposable file-backed fixtures and supported models, publish using <code>tools/publish_pxe.py --validated</code>. Do not edit <code>current.json</code> to mark missing media ready.</li><li>Return to Setup wizard → Components. Windows PXE boot media must show <strong>Validated</strong>. Select an enabled Windows preset, save and publish your existing routine draft.</li></ol><p>Build tools create regular files on the Windows workstation. Native capture and deployment require WinPE and reject running Windows. Automated deployment tests use disposable file-backed VM disks.</p>`},
{id:'boot',title:'WinPE boot media and restarts',description:'Boot ISO versus Windows image, firmware compatibility and the installation sequence.',body:()=>`<p>The re-pxe WinPE ISO starts the imaging environment. It is separate from the Windows <code>.wim</code> that is installed. PXE uses versioned iPXE, wimboot and WinPE files published in the server’s boot directory; Settings → Network shows the current DHCP filename.</p><ol><li>Use UEFI x64 network boot or the published re-pxe WinPE ISO. BIOS/ARM deployment is not supported by this workflow. Secure Boot is not yet validated.</li><li>WinPE enrolls the client, uses the routine’s Windows preset and exact pinned target, verifies and applies the image, then automatically restarts after successful installation.</li><li>Installed Windows starts the driver console. A countdown starts the automatic driver check; successful work restarts as needed and returns to the console’s main menu.</li><li>Use the console to install server drivers, upload exports, recheck devices or finish preparation. Finish performs the final checks and seals Windows for customer setup (OOBE).</li></ol><p>Keep the local disk as the normal startup device. Repeated forced network boot can prevent Windows completion. The server returns to the installed disk for enrolled clients with completion pending.</p><p>If WinPE cannot see the NIC or destination storage, include tested, signed AMD64 drivers in the boot media. Windows library drivers cannot fix a NIC that WinPE needs before enrollment.</p>`},
{id:'images',title:'Windows WIM preparation and publication',description:'Generalization, image index, build, hashing and review before deployment.',body:()=>`<p>Upload an AMD64 Windows <code>.wim</code>, not a Windows installer ISO or the re-pxe WinPE ISO. Select the correct index inside the WIM; a file can contain several editions. The server validates image metadata and records the selected Windows build.</p><ol><li>Customize a dedicated reference Windows installation in Audit Mode. Follow the project’s supported reference preparation procedure and run Sysprep with generalization and shutdown before capture. This workflow expects the deployed reference to enter Audit Mode for driver completion.</li><li>After shutdown, boot WinPE and capture the offline installation. Do not boot the generalized reference into installed Windows before capture. Native capture/deployment rejects running Windows.</li><li>Keep the original generalized reference separate from deployment tests. Use disposable file-backed fixtures for tests; never use the host’s physical Windows storage.</li><li>Calculate the WIM hash and check its index, then open Uploads → Windows image. Enter the hash, index and a clear preparation declaration. Upload, validate and review before publication.</li><li>Create and review a Windows preset for the published image, then choose it in a routine. Confirm model coverage, recovery and disk policy before enabling it.</li></ol><h3>Read-only file checks on Windows</h3><pre>Get-FileHash -Algorithm SHA256 -LiteralPath 'C:\\Images\\reference.wim'
DISM /Get-WimInfo /WimFile:C:\\Images\\reference.wim</pre><p>Use your actual WIM path. Publication records integrity and operator review; it does not prove licensing, hardware coverage or successful generalization by itself. See <a href="${guideSources.microsoft}" target="_blank" rel="noopener">Microsoft’s Sysprep generalization guidance</a>.</p>`},
{id:'drivers',title:'Driver tags, usage and cleanup',description:'Upload once, tag matching models, search and group drivers, then review deletion.',body:()=>`<ol><li>Export the driver files to a ZIP containing INFs and their supporting files. Upload through the native console or website; validated driver uploads enter the library automatically without approval.</li><li>Record manufacturer, exact model and Windows build, plus additional tested model tags if appropriate. The server validates archive integrity and applicable catalogs before publication.</li><li>The library stores individual INFs and shares identical files. Identical driver content reuses the entry and gains model tags. Add reviewed tags to reuse existing content on another tested model.</li><li>Search by name, provider, class, model, build, version, group or hash. Filter by usage/date or size in MiB, then sort and group the results. Custom groups organize cleanup; they do not replace model/build tags used for matching.</li><li>Select filtered drivers or a group, assign a custom group, or choose Delete selected. Selections can include hidden rows; the selection summary indicates this.</li></ol><h3>What “last used” means</h3><p>File requests and successful installs in authenticated job reports provide usage evidence. Each job counts once. “Confirmed” counts successful reported install actions. Viewing the catalog does not count as use. Older jobs without these records can show “Never recorded”. Stale uses the age threshold in General settings; never-used drivers have a separate filter.</p><h3>Deleting drivers</h3><p>The review lists every selected driver and any dependencies. Enabled explicit configurations, pinned PXE selections and active driver jobs block deletion. The server checks again when you confirm. Deletion withdraws the selected drivers and any legacy archives containing them from future selection. Completed reports keep their metadata.</p><p>Shared payload and archives referenced by saved configurations stay stored. Physical cleanup is deferred while deployments are active; later deletion operations retry it. Logical selected size can exceed reclaimed bytes. Reupload and review are required to restore deleted content.</p>`},
{id:'configurations',title:'Windows presets inside routines',description:'Reusable image, driver, recovery and Windows Update settings.',body:()=>`<p>A Windows preset is a component of a routine's Windows install step. It binds a published image, friendly Windows label, driver source, bounded Windows Update fallback and recovery options.</p><ol><li>Create and enable a preset under <strong>Windows presets</strong>. Images provides a Create Windows preset shortcut.</li><li>Choose it inside a routine, then save and publish the routine version. Changes require a replacement preset and a newly published routine; active jobs keep their original choices.</li><li>Set default and MAC assignments in <strong>Routines</strong>. Set disk selection per routine. Settings retains the global Windows disk policy and offline display interval.</li><li>Automatic drivers use matching server entries first, then Windows Update. Installed Windows retains the existing driver console, reboots and final OOBE preparation controls.</li></ol><p>Disabling a preset withdraws it from new routine execution. Earlier standalone sessions keep their recorded configuration and remain controllable under Jobs.</p>`},
{id:'accounts',title:'Users, passwords and certificate trust',description:'Website access, account administration and separate native credentials.',body:()=>`<p>Website users sign in with cookie sessions. Every website user currently has administrator access. Change the initial admin password in Settings → Users; new passwords require at least eight characters. The default-password reminder can be dismissed for this sign-in session; dismissal does not change account status.</p><p>Settings → Appearance saves System/Light/Dark mode and Teal/Blue/Amber theme for this browser. The header sun/moon button switches light and dark directly. Sidebar collapse is remembered too.</p><ul><li>Create an account per operator. Disabling a user prevents access; keep at least one enabled administrator.</li><li>Password changes sign that user out on all devices. Existing sessions expire, and changes require a session CSRF token.</li><li>Native API role tokens, scoped boot sessions and active-job credentials are separate from website accounts. Changing a website password does not rotate native tokens.</li><li>Verify and trust the gateway’s public root CA on authorized clients. Do not disable certificate verification or distribute the CA private key. WinPE media carries the public CA.</li><li>If login fails, check the account’s enabled status and correct server time. For certificate failures, verify the address, CA trust and client clock.</li></ul>`},
{id:'updates',title:'Portal software updates',description:'Enable update buttons once, check GitHub and recover interrupted updates.',body:()=>`<p>Open Settings → Server → Software updates to check the installed and available GitHub main revisions. Finish jobs and uploads, then choose Update now and confirm the revision and brief service restart. The page reconnects automatically.</p><p>Enable the host updater once from a clean installation checkout on the Linux Docker server: <code>python3 deploy/setup.py --address YOUR_SERVER_IP --portal-updates</code>. Keep the existing server address. Run setup as the usual Docker user (uid 1000); it uses sudo to install a systemd service. Host Python 3.12 or newer is required. See <code>docs/portal-updates.md</code> for installation details.</p><p>The updater builds before restarting, checks for active work again, preserves previous container versions and saves a verified database backup. A failed startup recovers the previous version. Windows client and WinPE media are published separately.</p><p>If interrupted, use Recover previous version. If the portal cannot start, stop <code>re-pxe-updater</code> with systemctl, run <code>python3 deploy/update_agent.py --root "$PWD" --recover</code> as the installation user, then start the service again. Maintenance stays enabled until recovery succeeds. Keep your independent backups.</p>`},
{id:'maintenance',title:'Storage, backups and troubleshooting',description:'Capacity, shared driver files, consistent backups and service checks.',body:()=>`<h3>Storage and backups</h3><p>Settings → Storage shows data-filesystem capacity, images, staging and shared driver blobs. Capacity may include other services. Driver logical size counts supporting files per INF; unique payload counts each hash once. Driver deletion may retain files for saved configurations or active work.</p><p><strong>Settings → Storage → Database backups and restore</strong> controls hourly scheduling, retention, NAS access, verified snapshot downloads and an explicitly confirmed restore. The database snapshot includes reports, original erasure PDFs, users, settings and logo. Published images, drivers, boot media and editable text files require a separate file backup. Restores preserve the current database, block active work, sign users out and revoke old machine credentials.</p><p>Schedule a quiet maintenance window with no deployments or uploads. Stop application writers before backing up the complete re-pxe data directory, <code>deploy/.env</code>, deployment configuration and persistent gateway CA volumes. Preserve file permissions and hardlinks, including the catalog SQLite database and any WAL files. Protect credentials and private CA material. Restore to an isolated server first, then verify image/driver hashes, accounts, configuration choices and trusted client access.</p><h3>Troubleshooting</h3><ul><li><strong>No PXE loader:</strong> check UEFI x64 firmware, NIC support, DHCP options, server IP, TFTP listener and transfer-port firewall rules.</li><li><strong>WinPE download fails:</strong> verify boot HTTP 8089 and the current versioned boot files.</li><li><strong>Enrollment/HTTPS fails:</strong> verify gateway 8443, certificate trust, address and client clock.</li><li><strong>Image rejected:</strong> verify SHA-256, AMD64 architecture, exact WIM index and reference preparation.</li><li><strong>No library driver match:</strong> check manufacturer/model spelling, reviewed tags and exact Windows build. Open Jobs to inspect remaining devices.</li><li><strong>Deletion blocked:</strong> finish the active job or disable the dependent explicit configuration, then open a fresh deletion review.</li></ul><p>Service ports shown in Settings are configuration, not a remote network test. This dashboard takes inspiration from imaging tools’ status pages; see the <a href="${guideSources.fog}" target="_blank" rel="noopener">FOG dashboard documentation</a>.</p>`}
];
function renderGuides(){const query=$('guide-search').value.toLocaleLowerCase();const matches=guides.filter(g=>(g.title+' '+g.description+' '+g.body().replace(/<[^>]*>/g,' ')).toLocaleLowerCase().includes(query));$('guide-list').innerHTML=matches.length?'<div class="guide-grid">'+matches.map(g=>'<button class="guide-card" data-guide="'+g.id+'"><strong>'+esc(g.title)+'</strong><span>'+esc(g.description)+'</span></button>').join('')+'</div>':empty('No guides match your search');if(activeGuide){const g=guides.find(g=>g.id===activeGuide);$('guide-article').hidden=false;$('guide-article').innerHTML='<button class="secondary compact" id="guide-back">All guides</button><h2>'+esc(g.title)+'</h2>'+g.body();$('guide-list').hidden=true;}else{$('guide-article').hidden=true;$('guide-list').hidden=false;}if(!guideEndpoints&&webSession)api('/server-info').then(d=>{guideEndpoints=d.endpoints;if(tab==='guides')renderGuides();}).catch(e=>message(e.message,true));}
$('guide-search').addEventListener('input',()=>{activeGuide=null;renderGuides();});
document.addEventListener('click',e=>{const b=e.target.closest('button[data-guide],#guide-back');if(!b)return;if(b.id==='guide-back'){activeGuide=null;renderGuides();rememberPortalNavigation();return;}activeGuide=b.dataset.guide;switchTab('guides');renderGuides();});
